if(StelMovementMgr.getFlagTracking()) {
    core.debug("Tracking is enabled");
} else {
    StelMovementMgr.setFlagTracking(true);
}

// Enable tracking of selected object
StelMovementMgr.setFlagTracking(true);

// Disable tracking
StelMovementMgr.setFlagTracking(false);

if(StelMovementMgr.getFlagLockEquPos()) {
    core.debug("Equatorial position is locked");
}

// Lock view to equatorial coordinates
StelMovementMgr.setFlagLockEquPos(true);

// Unlock (allow Earth rotation effect)
StelMovementMgr.setFlagLockEquPos(false);

if(StelMovementMgr.getEquatorialMount()) {
    core.debug("Equatorial mount mode");
} else {
    core.debug("Alt-azimuthal mount mode");
}

// Switch to equatorial mount
StelMovementMgr.setEquatorialMount(true);

// Switch to alt-azimuthal mount
StelMovementMgr.setEquatorialMount(false);

var mode = StelMovementMgr.getMountMode();
if(mode == 0) core.debug("Alt-Azimuthal mode");
if(mode == 1) core.debug("Equatorial mode");
if(mode == 2) core.debug("Galactic mode");
if(mode == 3) core.debug("Supergalactic mode");

// Set to equatorial mode
StelMovementMgr.setMountMode(1);

// Set to galactic mode
StelMovementMgr.setMountMode(2);

// Zoom in to 10 degrees
StelMovementMgr.setFov(10.0);

// Zoom out to 90 degrees
StelMovementMgr.setFov(90.0);

// Smooth zoom to 5 degrees over 2 seconds
StelMovementMgr.zoomTo(5.0, 2.0);

// Instant zoom
StelMovementMgr.zoomTo(60.0, 0);

// Start zooming in
StelMovementMgr.zoomIn(true);
core.wait(2);
// Stop zooming
StelMovementMgr.zoomIn(false);

StelMovementMgr.zoomOut(true);
core.wait(2);
StelMovementMgr.zoomOut(false);

// Select an object and zoom in
core.selectObjectByName("Mars", true);
StelMovementMgr.autoZoomIn(1.5, true);

// Quick zoom with no manual override
StelMovementMgr.autoZoomIn(0.5, false);

// Zoom out to see satellite system
StelMovementMgr.autoZoomOut(1.0, false);

// Zoom out fully to initial view
StelMovementMgr.autoZoomOut(2.0, true);

// Limit FOV to 180° for planetarium
StelMovementMgr.setUserMaxFov(180.0);

// No artificial limit (up to projection max)
StelMovementMgr.setUserMaxFov(360.0);

if(StelMovementMgr.getFlagAutoZoomOutResetsDirection()) {
    core.debug("Zoom out will reset view direction");
}

if(StelMovementMgr.getFlagEnableMoveAtScreenEdge()) {
    core.debug("Screen edge movement enabled");
}

if(StelMovementMgr.getFlagEnableMouseNavigation()) {
    core.debug("Mouse navigation enabled");
}

if(StelMovementMgr.getFlagEnableMouseZooming()) {
    core.debug("Mouse zooming enabled");
}

if(StelMovementMgr.getFlagEnableMoveKeys()) {
    core.debug("Arrow keys movement enabled");
}

if(StelMovementMgr.getFlagEnableZoomKeys()) {
    core.debug("Zoom keys enabled");
}

if(StelMovementMgr.getFlagIndicationMountMode()) {
    core.debug("Mount mode indicator visible");
}

// Faster auto-moves
StelMovementMgr.setAutoMoveDuration(0.8);

// Slower, more cinematic moves
StelMovementMgr.setAutoMoveDuration(3.0);

// Speed up for fast presentation
StelMovementMgr.setMovementSpeedFactor(2.0);

// Slow down for cinematic effect
StelMovementMgr.setMovementSpeedFactor(0.5);

// Look at coordinates (0h, 0°)
var dir = core.vec3d("0h", "0d");
StelMovementMgr.setViewDirectionJ2000(dir);

// Set standard up vector (celestial north is up)
var up = core.vec3d(0, 0, 1);
StelMovementMgr.setViewUpVectorJ2000(up);

// Set vertical up direction
var up = core.vec3d(0, 0, 1);
StelMovementMgr.setViewUpVector(up);

// Set current view as default
StelMovementMgr.setInitViewDirectionToCurrent();
core.debug("New default view direction saved");

// Move to celestial equator at 0h
var aim = core.vec3d("0h", "0d");
var up = core.vec3d(0, 0, 1);
StelMovementMgr.moveToJ2000(aim, up, 2.0, 0);

// Move to zenith
var aim = core.vec3d(0, 0, 1);
var up = core.vec3d(0, 0, 1);
StelMovementMgr.moveToAltAzi(aim, up, 1.5, 0);

// Start turning right
StelMovementMgr.turnRight(true);
core.wait(1);
StelMovementMgr.turnRight(false);

StelMovementMgr.turnLeft(true);
core.wait(1);
StelMovementMgr.turnLeft(false);

StelMovementMgr.turnUp(true);
core.wait(1);
StelMovementMgr.turnUp(false);

StelMovementMgr.turnDown(true);
core.wait(1);
StelMovementMgr.turnDown(false);

// Activate slow movement (Shift key)
StelMovementMgr.moveSlow(true);
StelMovementMgr.turnLeft(true);
core.wait(2);
StelMovementMgr.turnLeft(false);
StelMovementMgr.moveSlow(false);

// Look east at current altitude
StelMovementMgr.lookEast(false);

// Look east at horizon
StelMovementMgr.lookEast(true);

// Shift view down by 20% over 2 seconds
StelMovementMgr.moveViewport(0, 20, 2.0);

// Reset viewport
StelMovementMgr.moveViewport(0, 0, 1.0);

// Inhibit automatic movements
StelMovementMgr.setInhibitAllAutomoves(true);

// Allow automatic movements
StelMovementMgr.setInhibitAllAutomoves(false);
